{
  "lines": [
    {
      "text": "Von Danzig nach Königsberg und Memel."
    },
    {
      "text": "Den 25ten fuhren wir über die Nehrung nach Elbing, und den 28ten erreichten wir Königsberg"
    },
    {
      "text": "in Preußen. Hier besuchten wir den Professor Kant, der uns sehr höflich aufnahm, aber von"
    },
    {
      "text": "seiner Philosophie nicht reden wollte. Die Stadt besteht eigentlich aus drey Städten, Altstadt,"
    },
    {
      "text": "Löbenicht und Kneiphof."
    },
    {
      "text": "Den 30ten fuhren wir durch Neustadt, ein kleines Städtchen, dessen Namen man in Deutschland"
    },
    {
      "text": "wohl hundertmal findet, nach Labiau."
    },
    {
      "text": "Den 2. August kamen wir nach Memel, der letzten Stadt des Königreichs. Der Hafen war voll"
    },
    {
      "text": "von Schiffen aus Holland und England, welche Holz und Flachs laden."
    },
    {
      "text": "Den 5ten waren wir in Tilsit an der Memel, und kehrten von da über Insterburg nach"
    },
    {
      "text": "Königsberg zurück."
    },
    {
      "text": "Den 20ten August erreichten wir auf dem Rückwege Stettin, und den 23ten Colberg, wo dieses"
    },
    {
      "text": "Tagebuch schließt."
    }
  ],
  "script": "fraktur",
  "notes": "Single column, no visible damage or bleed-through. Text is clearly printed in Fraktur typeface."
}

